/**
 * `agent-sdk mcp oauth <connection> [--store]`.
 *
 * Host MCP OAuth for `defineConnection({ url, oauth: true })`: local tokens,
 * optionally stored as secrets on the hosted v2 deployment. A
 * `defineConnection({ cursorAccount: true })` connection authorizes from the
 * dashboard: v2 deployments do not expose the service account the CLI flow
 * authorizes.
 */
import { UnauthorizedError } from "@modelcontextprotocol/sdk/client/auth.js";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { SSEClientTransport } from "@modelcontextprotocol/sdk/client/sse.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { isCursorAccountTransport } from "../types.js";
import { resolveDeployAuth } from "./cli-deploy.js";
import { resolveConnectionEnvTemplates } from "./connection-env.js";
import { loadAgentProject } from "./discovery.js";
import { CLI_COMMAND_NAME as CLI, LOG_PREFIX } from "./distribution.js";
import { createHostMcpOAuthProvider, MCP_OAUTH_CALLBACK_URL, openBrowser, waitForMcpOAuthCallback, } from "./mcp-oauth.js";
import { upsertHostMcpOauthSecrets } from "./mcp-oauth-persist.js";
import { resolveProdSlug } from "./resolve-prod-target.js";
function describe(error) {
    if (!(error instanceof Error)) {
        return String(error);
    }
    const cause = error.cause;
    if (!(cause instanceof Error)) {
        return error.message;
    }
    const code = "code" in cause && typeof cause.code === "string" ? cause.code : undefined;
    const detail = code === undefined ? cause.message : `${cause.message} (${code})`;
    return `${error.message}: ${detail}`;
}
export async function cmdMcpOauth(options) {
    const err = options.err ?? ((text) => process.stderr.write(text));
    const out = options.out ?? ((text) => process.stdout.write(text));
    const project = await loadAgentProject(options.dir);
    const authored = [...project.agent.connections, ...(project.agent.hostConnections ?? [])];
    const connection = authored.find((entry) => entry.name === options.connection);
    if (connection === undefined) {
        const known = authored.map((entry) => entry.name).join(", ") || "(none)";
        err(`${LOG_PREFIX} Unknown MCP connection "${options.connection}". Authored: ${known}.\n`);
        return 1;
    }
    const transport = resolveConnectionEnvTemplates(connection.transport);
    if (isCursorAccountTransport(transport)) {
        err(`${LOG_PREFIX} "${options.connection}" is a cursorAccount connection. Authorize its connectors ` +
            `from the cursor.com dashboard (Deployed Agents → your deployment). \`${CLI} mcp oauth\` ` +
            `does not support cursorAccount connections on v2 deployments yet.\n`);
        return 1;
    }
    if (!("url" in transport) || transport.oauth !== true) {
        err(`${LOG_PREFIX} "${options.connection}" must be defineConnection({ url, oauth: true }) or defineConnection({ cursorAccount: true }).\n`);
        return 1;
    }
    if (options.dryRun === true) {
        out(`Dry run: would open the OAuth sign-in for "${options.connection}" (${transport.url}) and ` +
            `save its tokens in the local token store` +
            (options.store === true
                ? `, then store them as MCP_OAUTH_* secrets on the hosted deployment.`
                : ".") +
            " Nothing changed.\n");
        return 0;
    }
    const flow = await authorizeHostMcpOauth({
        connection: options.connection,
        url: transport.url,
        type: transport.type === "sse" ? "sse" : "http",
        headers: transport.headers,
        out,
        err,
    });
    if (!flow.ok) {
        return 1;
    }
    if (options.store !== true) {
        return 0;
    }
    return storeOauthSecrets({
        connection: options.connection,
        dir: options.dir,
        slug: options.slug,
        team: options.team,
        apiKey: options.apiKey,
        tokens: flow.tokens,
        clientId: flow.clientId,
        err,
        out,
    });
}
/**
 * The interactive host-OAuth browser flow against an MCP server URL. Takes
 * the transport metadata directly so callers that already hold it never have
 * to load the authored project to authorize.
 */
export async function authorizeHostMcpOauth(args) {
    const { connection, out, err } = args;
    out(`${LOG_PREFIX} Authorizing "${connection}" (${args.url})…\n`);
    let authorizationUrl;
    const provider = await createHostMcpOAuthProvider({
        identifier: connection,
        resourceUrl: args.url,
        onRedirect: (url) => {
            authorizationUrl = url;
        },
    });
    const client = new Client({ name: "agent-sdk-mcp-oauth", version: "0.1.0" });
    const url = new URL(args.url);
    const requestInit = args.headers === undefined ? undefined : { headers: args.headers };
    const makeTransport = () => {
        if (args.type === "sse") {
            return new SSEClientTransport(url, {
                authProvider: provider,
                requestInit,
            });
        }
        return new StreamableHTTPClientTransport(url, {
            authProvider: provider,
            requestInit,
        });
    };
    let mcpTransport = makeTransport();
    let authorized = false;
    try {
        await client.connect(mcpTransport);
        out(`${LOG_PREFIX} "${connection}" already authorized.\n`);
        await client.close().catch(() => undefined);
        authorized = true;
    }
    catch (error) {
        if (!(error instanceof UnauthorizedError)) {
            err(`${LOG_PREFIX} Failed to connect to "${connection}": ${describe(error)}\n`);
            return { ok: false };
        }
    }
    if (!authorized) {
        const redirect = authorizationUrl ?? provider.lastRedirectUrl;
        if (redirect === undefined) {
            err(`${LOG_PREFIX} Auth required but no authorization URL was provided.\n`);
            return { ok: false };
        }
        out(`${LOG_PREFIX} Open if needed:\n  ${redirect.toString()}\n`);
        out(`${LOG_PREFIX} Waiting on ${MCP_OAUTH_CALLBACK_URL}…\n`);
        openBrowser(redirect.toString());
        let callback;
        try {
            callback = await waitForMcpOAuthCallback({
                authorizationUrl: redirect.toString(),
            });
        }
        catch (error) {
            err(`${LOG_PREFIX} OAuth callback failed: ${describe(error)}\n`);
            return { ok: false };
        }
        try {
            await mcpTransport.finishAuth(callback.code);
        }
        catch (error) {
            err(`${LOG_PREFIX} Token exchange failed: ${describe(error)}\n`);
            return { ok: false };
        }
        mcpTransport = makeTransport();
        try {
            await client.connect(mcpTransport);
            const tools = await client.listTools();
            out(`${LOG_PREFIX} Authorized "${connection}" (${tools.tools.length} tools). Local tokens in the agent-serve config dir.\n`);
            await client.close().catch(() => undefined);
        }
        catch (error) {
            err(`${LOG_PREFIX} Reconnect failed: ${describe(error)}. Re-run \`${CLI} mcp oauth ${connection}\`.\n`);
            return { ok: false };
        }
    }
    return {
        ok: true,
        tokens: provider.tokens(),
        clientId: provider.clientInformation()?.client_id,
    };
}
async function storeOauthSecrets(args) {
    const tokens = args.tokens;
    if (tokens === undefined || tokens.access_token.trim() === "") {
        args.err(`${LOG_PREFIX} No access token to store for "${args.connection}".\n`);
        return 1;
    }
    let slug;
    try {
        slug = resolveProdSlug({ dir: args.dir, slug: args.slug });
    }
    catch (error) {
        args.err(`${LOG_PREFIX} ${describe(error)}\n`);
        return 1;
    }
    const auth = await resolveDeployAuth({
        team: args.team,
        apiKey: args.apiKey,
        err: args.err,
    });
    if (typeof auth === "number") {
        return auth;
    }
    try {
        const secretNames = await upsertHostMcpOauthSecrets({
            connection: args.connection,
            tokens,
            clientId: args.clientId,
            target: {
                client: { setSecrets: (request) => auth.client.setAgentkitSecrets(request) },
                teamId: auth.teamId,
                slug,
            },
        });
        args.out(`${LOG_PREFIX} Stored on ${slug}. Secrets now: ${secretNames.join(", ")}. The next task picks them up.\n`);
        return 0;
    }
    catch (error) {
        args.err(`${LOG_PREFIX} Failed to store secrets on ${slug}: ${describe(error)}\n`);
        return 1;
    }
}
